import { onMounted, onBeforeUnmount } from 'vue'

onMounted(() => {
  // DOM が出来上がっている。addEventListener や 3rd party 初期化はここで
  window.addEventListener('resize', onResize)
})

onBeforeUnmount(() => {
  // 後片付け。addEventListener は必ず removeEventListener と対で
  window.removeEventListener('resize', onResize)
})

// ❌ SSR で ReferenceError: window is not defined
<script setup lang="ts">
const width = ref(window.innerWidth) // setup 本体はサーバでも走る
</script>

// ✅ クライアント限定の処理は onMounted に
<script setup lang="ts">
const width = ref(0)
onMounted(() => {
  width.value = window.innerWidth
})
</script>
